const rates=[47.73,47.77,47.82,47.87,47.93,47.99,48.05,48.13,48.22,48.31,48.42,48.54,48.67,48.83,49,49.20,49.43,49.69,49.99,50.32,50.71,51.14,51.63,52.17,52.79,53.47,54.23,55.07,56,57.02,58.13,59.35,60.66,62.09,63.62,65.27];
const f=document.querySelector('#form'),els=f.elements,preview=document.querySelector('#preview'),msg=document.querySelector('#message');let currentId=null;
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>Number.isFinite(n)?'Rs. '+Math.round(n).toLocaleString('en-IN')+'/=':'—';
function ageForDate(value){const b=new Date(value+'T00:00:00'),t=new Date();if(!value||Number.isNaN(b.getTime())||b>t)return null;let a=t.getFullYear()-b.getFullYear();if(t.getMonth()<b.getMonth()||(t.getMonth()===b.getMonth()&&t.getDate()<b.getDate()))a--;return a}
function data(){return Object.fromEntries(new FormData(f))}
function calc(){let age=Number(els.age.value),sum=Number(els.sum.value),term=Number(els.term.value);let ok=els.age.value!==''&&Number.isInteger(age)&&age>=1&&age<=55&&els.sum.value!==''&&Number.isSafeInteger(sum)&&sum>0&&sum<=249999999999;let rate=ok?rates[Math.max(age,20)-20]:null;let premium=ok?Math.round(sum*(Math.round(rate*100)+125-(sum>=300000?50:0))/100000)+100:NaN;for(const [id,v] of Object.entries({premium,total:premium*term,maturity:ok?sum*4:NaN,accidental:ok?sum*2:NaN,normal:ok?sum:NaN}))document.getElementById(id).textContent=money(v);document.querySelector('#rate').textContent=ok?`Basic rate: ${rate.toFixed(2)} per 1,000 · accidental benefit +1.25${sum>=300000?' · sum assured adjustment −0.50':''} · policy fee Rs. 100`:'Enter a valid age (1–55) and sum assured to calculate.';return {ok,age,sum,term,premium,maturity:sum*4,accidental:sum*2}}
function dates(){if(els.dob.value){let a=ageForDate(els.dob.value);els.age.value=a??'';els.age.readOnly=true;els.dob.setCustomValidity(a===null?'Choose a date that is not in the future.':'');document.querySelector('#ageHint').textContent='Calculated from date of birth.'}else{els.age.readOnly=false;els.dob.setCustomValidity('');document.querySelector('#ageHint').textContent='Enter an age or select a date of birth.'}calc()}
f.addEventListener('input',e=>{if(e.target===els.dob)dates();else calc();msg.textContent=''});els.dob.max=new Date().toLocaleDateString('en-CA');
function saved(){try{let v=JSON.parse(localStorage.getItem('proposal-studio-v1')||'[]');return Array.isArray(v)?v:[]}catch{return []}}
function renderSaved(){const target=document.querySelector('#saved');target.replaceChildren();let list=saved();if(!list.length){target.textContent='No saved proposals yet.';target.className='muted';return}target.className='';list.forEach(p=>{let box=document.createElement('div');box.className='saved-item';let title=document.createElement('strong');title.textContent=p.values.customerName;box.append(title);let actions=document.createElement('div');for(const [label,fn] of [['Open',()=>{for(const [k,v] of Object.entries(p.values))if(els[k])els[k].value=v;currentId=p.id;dates();window.scrollTo({top:0,behavior:'smooth'})}],['Duplicate',()=>{for(const [k,v] of Object.entries(p.values))if(els[k])els[k].value=v;currentId=null;dates();window.scrollTo({top:0,behavior:'smooth'})}],['Delete',()=>{if(confirm('Delete this saved proposal?')){localStorage.setItem('proposal-studio-v1',JSON.stringify(saved().filter(x=>x.id!==p.id)));renderSaved()}}]]){let b=document.createElement('button');b.textContent=label;b.type='button';b.onclick=fn;actions.append(b)}box.append(actions);target.append(box)})}
document.querySelector('#save').onclick=()=>{if(!f.reportValidity()||!calc().ok)return;try{let list=saved(),id=currentId||crypto.randomUUID(),item={id,values:data(),updated:Date.now()};localStorage.setItem('proposal-studio-v1',JSON.stringify([item,...list.filter(p=>p.id!==id)]));currentId=id;renderSaved();msg.textContent='Proposal saved on this device.'}catch{msg.textContent='Could not save on this device. Check browser storage settings.'}};
document.querySelector('#reset').onclick=()=>{f.reset();currentId=null;dates();msg.textContent=''};
function buildPages(d,c){const x=escapeHTML;let contact=[['Phone',d.phone],['Email',d.email],['Address',d.address]].filter(([,v])=>v?.trim()).map(([k,v])=>`${k}: ${x(v)}`).join('<br>');let header='<header><b>STATE LIFE INSURANCE</b><br>CORPORATION OF PAKISTAN</header>';let foot=(text,n)=>`<div class="pagefoot">${text}</div><div class="number">${n}</div>`;return `<article class="paper">${header}<div class="cover"><p>IN THE NAME OF ALLAH, MOST BENEFICIENT<br>AND THE MOST MERCIFUL</p><div class="box"><b>FINANCIAL PROGRAMME FOR</b><p class="name">${x(d.customerName.toUpperCase())}</p>${contact}</div><h3>GUARANTEE BY FEDERAL GOVERNMENT</h3><p>THE SUM INSURED INCLUDING BONUSES DECLARED UNDER THE POLICY ARE GUARANTEED AS TO PAYMENT IN CASH BY THE FEDERAL GOVERNMENT UNDER THE ARTICLE 35 OF LIFE INSURANCE NATIONALIZATION ORDER # 10 OF 1972.</p></div>${foot('HAPPY LIFE WITH STATE LIFE · STATE LIFE IS GREAT LIFE',1)}</article><article class="paper">${header}<h3>SAVING AND RISK COVERAGE PLAN FOR BELOVED FAMILY</h3><table><tr><td>Age</td><td>${c.age} Years</td></tr><tr><td>Term</td><td>${c.term} Years</td></tr><tr><td>Sum Assured</td><td>${money(c.sum)}</td></tr></table><h3>PAYMENT OF PREMIUM</h3><table><tr><td>Total Premium Yearly</td><td>${money(c.premium)}</td></tr><tr><td>Total premium over the term</td><td>${money(c.premium*c.term)}</td></tr></table><h3>Maturity</h3><p>Estimated maturity: ${money(c.maturity)} (approximate). This is an illustrative proposal value, subject to policy terms and applicable bonus rates.</p><h3>INTERNATIONAL POLICY</h3><p>This is an international policy and provides coverage all over the world.</p><h3>FLEXIBLE POLICY</h3><p>This is a flexible policy and can be increased or decreased according to needs.</p>${foot('YOUR LIFE IS PRECIOUS FOR YOUR LOVED ONES',2)}</article><article class="paper">${header}<h3>IN CASE OF ACCIDENTAL DEATH</h3><p>(1) State Life will pay ${money(c.accidental)} at once.<br>(2) Bonuses on paid premiums and<br>(3) Premium installment would be waived off.</p><h3>IN CASE OF NORMAL DEATH</h3><p>(1) State Life will pay ${money(c.sum)} at once.<br>(2) Bonuses on paid premiums and<br>(3) Premium installment would be waived off.</p><h3>MEDICAL FACILITIES</h3><p>For eligible operations for chronic diseases: after 5 years, maximum Rs. 2,50,000/=; after 10 years, maximum Rs. 5,00,000/=. Coverage is limited to 50% of the sum assured and is subject to policy terms and approval.</p><h3>LOAN</h3><p>The loan facilities are available after 3 years.</p><p><b>STATE LIFE INSURANCE<br>Corporation of Pakistan</b> &nbsp;&nbsp; With Best Wishes</p>${foot('EVEN A BEST SHIP CARRIES LIFE BOATS',3)}</article>`}
f.addEventListener('submit',e=>{e.preventDefault();if(!f.reportValidity())return;let c=calc();if(!c.ok)return;document.querySelector('#pages').innerHTML=buildPages(data(),c);preview.hidden=false;preview.scrollTop=0});document.querySelector('#close').onclick=()=>{preview.hidden=true};document.querySelector('#print').onclick=()=>window.print();window.addEventListener('keydown',e=>{if(e.key==='Escape'&&!preview.hidden)preview.hidden=true});dates();renderSaved();
